package com.vandorlabs.neoforge.reservoir;
import com.vandorlabs.neoforge.*;import com.vandorlabs.persistence.HousingSettings;import com.vandorlabs.ui.ProgrammableBlockDialog;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.block.entity.BlockEntityType;import net.minecraft.world.level.block.state.BlockState;
/** Per-cell storage owner; only known housing, shape and visible contents are sent to clients. */
public abstract class NativeBufferEntity extends ProgrammableBlockEntity {
 public static final String RECOVERY="NativeBufferPlacementRecovery";private long publishedResourceUpdates;
 private final NativeBufferOutput fullness=new NativeBufferOutput(this);
 public final NativeBufferOutput fullness(){return fullness;}
 public final boolean configureOutput(Player player,com.vandorlabs.redstone.ChannelList channels,int range,boolean local){
  if(!installed()||!NativeConfigurationAccess.canEditDialog(player,this)||!com.vandorlabs.redstone.TransmissionSettings.validConfiguration(channels,range))return false;
  fullness.configure(channels,range,local);publish(false);return true;
 }
 final long resourcePublicationCount(){return publishedResourceUpdates;}
 private boolean block,inert,customCasing,unloading,dirty,forcedRecovery;private int syncTicks;private CompoundTag failed;
 protected NativeBufferEntity(BlockEntityType<?> type,BlockPos pos,BlockState state,boolean block){super(type,pos,state,defaults());this.block=block;}
 public final boolean blockShape(){return block;}public final boolean inert(){return inert;}public final int casing(){return this instanceof NativeBatteryEntity&&!customCasing?-1:settings().mainTexture;}
 public final Direction facing(){return getBlockState().getValue(NativeBufferBlock.FACING);}
 public final boolean installed(){if(inert||unloading||isRemoved()||!(level instanceof ServerLevel server)||!server.getServer().isSameThread())return false;var chunk=server.getChunkSource().getChunkNow(worldPosition.getX()>>4,worldPosition.getZ()>>4);return chunk!=null&&chunk.getBlockEntities().get(worldPosition)==this&&chunk.getBlockState(worldPosition)==getBlockState()&&!com.vandorlabs.neoforge.placement.NativeStationaryPlacement.mutating(level,worldPosition)&&!com.vandorlabs.neoforge.ramp.NativeRampHeldOwners.blocked(level,worldPosition);}
 public final boolean configure(Player player,int casing,int layout,boolean block){if(!installed()||!NativeConfigurationAccess.canEditDialog(player,this)||(!(this instanceof NativeBatteryEntity&&casing==-1)&&!ModernFinishCatalog.validChoice(casing))||(layout!=1&&layout!=2)||this instanceof NativeBatteryEntity&&layout!=1)return false;this.block=block;installCasing(casing,layout);casingConfigured(casing);changed();return true;}
 protected final void installCasing(int choice,int layout){customCasing=choice!=-1;updateSettings(new ProgrammableBlockDialog.State(choice==-1?0:choice,layout,false,new int[]{-1,-1,-1,-1,-1,-1},-1));}
 protected void casingConfigured(int choice){}
 protected final void contentsChanged(){contentsChanged(false);}
 protected final void contentsChanged(boolean fluidIdentityChanged){setChanged();dirty=true;if(fluidIdentityChanged&&this instanceof NativeHexTankEntity)NativeTankGroups.invalidate(level);}
 protected final void changed(){dirty=false;publish(true);}
 private void publish(boolean topologyChanged){setChanged();if(topologyChanged&&this instanceof NativeHexTankEntity)NativeTankGroups.invalidate(level);if(level!=null){if(level.isClientSide)requestModelDataUpdate();level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),2);}}
 final void forceRecovery(boolean value){forcedRecovery=value;}final boolean takeRecovery(){boolean value=forcedRecovery;forcedRecovery=false;return value;}
 public final void serverTick(){if(installed()&&++syncTicks>=5){syncTicks=0;if(dirty){dirty=false;publishedResourceUpdates++;fullness.publish();publish(false);}}}
 protected abstract void readContents(CompoundTag tag,HolderLookup.Provider registries);protected abstract void writeContents(CompoundTag tag,HolderLookup.Provider registries);public abstract int amount();public abstract int capacity();
 @Override protected final void loadAdditional(CompoundTag tag,HolderLookup.Provider registries){if(level!=null&&level.isClientSide){readPublic(tag,registries);return;}inert=true;failed=tag.copy();try{NativePlatformComponents.requireSupported(tag,registries);if(tag.contains(RECOVERY)||tag.contains("NativeBufferSchema")&&(!tag.contains("NativeBufferSchema",Tag.TAG_INT)||tag.getInt("NativeBufferSchema")!=1))throw new IllegalArgumentException("Unsupported storage owner");if(tag.contains("ForgeCaps")&&(!tag.contains("ForgeCaps",Tag.TAG_COMPOUND)||!tag.getCompound("ForgeCaps").isEmpty()))throw new IllegalArgumentException("Unsupported legacy storage capabilities");CompoundTag housing=tag;if(this instanceof NativeBatteryEntity&&!tag.contains(HousingSettings.MAIN)&&tag.contains("HousingTexture",Tag.TAG_INT)){housing=tag.copy();housing.putInt(HousingSettings.MAIN,tag.getInt("HousingTexture"));housing.putInt(HousingSettings.VERSION,1);}try(var platform=NativePlatformComponents.guardLoad(this)){super.loadAdditional(housing,registries);platform.requireSuccessful();}block=tag.contains("BlockShape")?tag.getBoolean("BlockShape"):this instanceof NativeBatteryEntity;customCasing=tag.contains(HousingSettings.MAIN,Tag.TAG_INT)||this instanceof NativeBatteryEntity&&tag.contains("HousingTexture",Tag.TAG_INT);readContents(tag,registries);fullness.load(tag);inert=false;failed=null;}catch(RuntimeException unsupported){inert=true;}if(this instanceof NativeHexTankEntity)NativeTankGroups.invalidate(level);}
 @Override protected final void saveAdditional(CompoundTag tag,HolderLookup.Provider registries){if(inert&&failed!=null){tag.merge(failed.copy());NativePlatformComponents.clearForInertSave(this);return;}super.saveAdditional(tag,registries);if(this instanceof NativeBatteryEntity){tag.remove("HousingTexture");if(!customCasing)tag.remove(HousingSettings.MAIN);}tag.putInt("NativeBufferSchema",1);tag.putBoolean("BlockShape",block);writeContents(tag,registries);fullness.write(tag);}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider registries){var tag=new CompoundTag();tag.putBoolean("NativeBufferInert",inert);if(inert)return tag;HousingSettings.write(new ModernHousingTags(tag),settings().mainTexture,-1,settings().layout,settings().layout==1,false,new int[]{-1,-1,-1,-1,-1,-1});if(this instanceof NativeBatteryEntity&&!customCasing)tag.remove(HousingSettings.MAIN);tag.putBoolean("BlockShape",block);writeContents(tag,registries);fullness.write(tag);return tag;}
 private void readPublic(CompoundTag tag,HolderLookup.Provider registries){
  boolean previousInert=inert,previousBlock=block;int previousTexture=settings().mainTexture,previousLayout=settings().layout;
  var previousFluid=this instanceof NativeHexTankEntity tank?tank.storedFluid():net.neoforged.neoforge.fluids.FluidStack.EMPTY;
  inert=tag.getBoolean("NativeBufferInert");
  if(!inert){super.loadAdditional(tag,registries);block=tag.contains("BlockShape")?tag.getBoolean("BlockShape"):this instanceof NativeBatteryEntity;customCasing=tag.contains(HousingSettings.MAIN,Tag.TAG_INT);try{readContents(tag,registries);fullness.load(tag);}catch(RuntimeException invalid){inert=true;}}
  if(this instanceof NativeHexTankEntity tank){var current=tank.storedFluid();if(previousInert!=inert||previousBlock!=block||previousTexture!=settings().mainTexture||previousLayout!=settings().layout||previousFluid.isEmpty()!=current.isEmpty()||!previousFluid.isEmpty()&&!net.neoforged.neoforge.fluids.FluidStack.isSameFluidSameComponents(previousFluid,current))NativeTankGroups.invalidate(level);}
  requestModelDataUpdate();
 }
 @Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider registries){readPublic(tag,registries);if(level!=null&&level.isClientSide)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),2);}
 @Override public void onLoad(){super.onLoad();unloading=false;fullness.loaded();if(this instanceof NativeHexTankEntity)NativeTankGroups.invalidate(level);}@Override public void onChunkUnloaded(){unloading=true;fullness.unloaded();if(this instanceof NativeHexTankEntity)NativeTankGroups.invalidate(level);super.onChunkUnloaded();}@Override public void setRemoved(){unloading=true;fullness.unloaded();if(this instanceof NativeHexTankEntity)NativeTankGroups.invalidate(level);super.setRemoved();}
}
